function _setVH(){const h=(window.visualViewport?window.visualViewport.height:window.innerHeight)*0.01;document.documentElement.style.setProperty('--vh',h+'px');}
_setVH();window.addEventListener('resize',_setVH);window.addEventListener('orientationchange',_setVH);

const MAX_CARD_FIELD=12*1024*1024;
function toast(msg,type,action){const t=document.getElementById('toast');t.innerHTML='';const sp=document.createElement('span');sp.textContent=msg;t.appendChild(sp);if(action&&action.fn){const b=document.createElement('button');b.textContent=action.label||'Undo';b.style.cssText='margin-left:12px;background:transparent;border:1px solid currentColor;color:inherit;border-radius:6px;padding:2px 10px;font-size:11px;cursor:pointer;font-family:inherit;';b.onclick=()=>{t.className='';clearTimeout(t._t);try{action.fn();}catch(e){console.error(e);}};t.appendChild(b);}t.className='show '+(type||'info');clearTimeout(t._t);t._t=setTimeout(()=>{t.className='';},action?6500:2600);}

