let COLOR_FAVORITES=[],COLOR_RECENTS=[];
const COLOR_PALETTE=["#ffffff","#d0d0d8","#9090a8","#5a5a72","#f87171","#fb923c","#fbbf24","#facc15","#a3e635","#4ade80","#34d399","#22d3ee","#60a5fa","#818cf8","#a78bfa","#f472b6"];
async function DB_loadColors(){try{const i=await db.info.get('info');COLOR_FAVORITES=Array.isArray(i&&i.colorFavorites)?i.colorFavorites:[];COLOR_RECENTS=Array.isArray(i&&i.colorRecents)?i.colorRecents:[];}catch(e){}}
async function DB_saveColors(){try{await db.info.update('info',{colorFavorites:COLOR_FAVORITES,colorRecents:COLOR_RECENTS});}catch(e){}}
function normalizeHex(v){if(!v)return null;v=String(v).trim().toLowerCase();if(/^[0-9a-f]{6}$/.test(v))v="#"+v;if(/^[0-9a-f]{3}$/.test(v))v="#"+v[0]+v[0]+v[1]+v[1]+v[2]+v[2];return /^#[0-9a-f]{6}$/.test(v)?v:null;}
function pushRecentColor(hex){hex=normalizeHex(hex);if(!hex)return;COLOR_RECENTS=[hex,...COLOR_RECENTS.filter(c=>c!==hex)].slice(0,8);DB_saveColors();}
function addFavoriteColor(hex){hex=normalizeHex(hex);if(!hex)return false;if(COLOR_FAVORITES.includes(hex))return false;COLOR_FAVORITES=[...COLOR_FAVORITES,hex].slice(0,18);DB_saveColors();return true;}
function removeFavoriteColor(hex){COLOR_FAVORITES=COLOR_FAVORITES.filter(c=>c!==hex);DB_saveColors();}

