  document.addEventListener("paste",e=>{if(!_draw||_draw.modal.style.display==="none")return;const items=e.clipboardData&&e.clipboardData.items;if(!items)return;for(const it of items){if(it.type.indexOf("image")===0){e.preventDefault();_drawLoadFile(it.getAsFile());return;}}});
